import{_ as t,r as e,o as r,c as o,a as i,b as n,d as s,e as d}from"./app.ChrdILIc.js";import"./chunks/three-vendor.DK3fmyXa.js";const m=JSON.parse('{"title":"开发模式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/development/type.md","filePath":"zh/development/type.md","lastUpdated":1778395361000}'),h={name:"zh/development/type.md"};function c(u,l,g,p,b,k){const a=e("ArticleMetadata");return r(),o("div",null,[l[0]||(l[0]=i("h1",{id:"开发模式",tabindex:"-1"},[n("开发模式 "),i("a",{class:"header-anchor",href:"#开发模式","aria-label":'Permalink to "开发模式"'},"​")],-1)),s(a),l[1]||(l[1]=d('<p><code>/development/type</code> 用于说明团队在不同项目阶段应该采用什么样的交付方式，以及每种方式下的最低质量要求。</p><h2 id="什么时候用哪种模式" tabindex="-1">什么时候用哪种模式 <a class="header-anchor" href="#什么时候用哪种模式" aria-label="Permalink to &quot;什么时候用哪种模式&quot;">​</a></h2><p>团队通常采用两种工作方式：</p><table tabindex="0"><thead><tr><th style="text-align:left;">模式</th><th style="text-align:left;">适用场景</th><th style="text-align:left;">目标</th><th style="text-align:left;">典型节奏</th></tr></thead><tbody><tr><td style="text-align:left;">标准开发流程</td><td style="text-align:left;">需求明确、影响范围大、需要稳定交付的项目</td><td style="text-align:left;">降低风险，保证质量与可追踪性</td><td style="text-align:left;">以里程碑或版本为单位</td></tr><tr><td style="text-align:left;">快速迭代模式</td><td style="text-align:left;">需求还在探索、需要快速验证价值的项目</td><td style="text-align:left;">尽快拿到反馈，缩短试错周期</td><td style="text-align:left;">以天或周为单位</td></tr></tbody></table><p>选择模式时不要只看“快不快”，而要综合判断以下三个维度：</p><ul><li><strong>需求稳定性</strong>：需求是否已经明确，是否存在频繁变动的可能。</li><li><strong>业务风险</strong>：功能是否涉及支付、权限、数据安全、核心链路。</li><li><strong>协作复杂度</strong>：是否需要多角色协同，例如产品、设计、前后端、测试、运维同时参与。</li></ul><h2 id="通用原则" tabindex="-1">通用原则 <a class="header-anchor" href="#通用原则" aria-label="Permalink to &quot;通用原则&quot;">​</a></h2><p>无论采用哪种开发模式，都应满足以下共识：</p><ul><li><strong>先对齐目标，再开始编码</strong>：每个迭代都要明确目标、范围、验收标准。</li><li><strong>小步交付，持续验证</strong>：尽量将工作拆小，避免“大功能一次性上线”。</li><li><strong>文档与代码同步更新</strong>：需求变更、接口变更、部署说明要及时沉淀。</li><li><strong>问题尽早暴露</strong>：风险、阻塞、依赖、资源不足应尽早同步，不要等到延期时才反馈。</li><li><strong>质量底线不可省略</strong>：无论多赶，都不能跳过基本测试、代码审查和上线验证。</li></ul><h2 id="基于-docker-的开发方式" tabindex="-1">基于 Docker 的开发方式 <a class="header-anchor" href="#基于-docker-的开发方式" aria-label="Permalink to &quot;基于 Docker 的开发方式&quot;">​</a></h2><p>对于现代团队协作，推荐采用 <strong>docker-first</strong> 的开发思路：尽可能把项目运行环境、依赖服务和联调链路都放进 Docker，但不必执着于把所有个人工作工具都容器化。</p><h3 id="推荐态度" tabindex="-1">推荐态度 <a class="header-anchor" href="#推荐态度" aria-label="Permalink to &quot;推荐态度&quot;">​</a></h3><ul><li><strong>尽量 all in Docker，但不强求 docker-only</strong>：项目环境可以高度容器化，个人工作环境不必全部搬进去。</li><li><strong>统一环境优先于个人习惯</strong>：相比“每个人本机都能跑但配置不一样”，更推荐团队共享同一套容器化环境。</li><li><strong>让 Docker 服务于开发效率</strong>：容器化的目标是降低环境成本、减少联调问题、提升可复制性，而不是增加额外负担。</li></ul><h3 id="适合放进-docker-的内容" tabindex="-1">适合放进 Docker 的内容 <a class="header-anchor" href="#适合放进-docker-的内容" aria-label="Permalink to &quot;适合放进 Docker 的内容&quot;">​</a></h3><ul><li>前端、后端、BFF、网关等业务服务</li><li>MySQL、PostgreSQL、Redis、MongoDB 等基础依赖</li><li>消息队列、对象存储、本地 mock 服务</li><li>测试环境依赖、联调依赖、CI 所需运行环境</li><li>Node、Java、Python、Go 等语言运行时和构建环境</li></ul><h3 id="不必强行放进-docker-的内容" tabindex="-1">不必强行放进 Docker 的内容 <a class="header-anchor" href="#不必强行放进-docker-的内容" aria-label="Permalink to &quot;不必强行放进 Docker 的内容&quot;">​</a></h3><ul><li>IDE 本体</li><li>浏览器</li><li>系统级代理、输入法、剪贴板工具</li><li>设计软件、桌面协作工具</li><li>强依赖图形界面或本机硬件的开发工具</li></ul><h3 id="为什么推荐-docker-first" tabindex="-1">为什么推荐 Docker-first <a class="header-anchor" href="#为什么推荐-docker-first" aria-label="Permalink to &quot;为什么推荐 Docker-first&quot;">​</a></h3><ul><li><strong>环境一致</strong>：减少“我电脑可以，你电脑不行”的问题。</li><li><strong>新成员上手快</strong>：通过 <code>docker compose up</code> 即可拉起核心依赖。</li><li><strong>联调更稳定</strong>：数据库、缓存、队列、网关版本更容易统一。</li><li><strong>更接近生产环境</strong>：便于提前发现配置、网络、端口和依赖问题。</li><li><strong>便于自动化</strong>：本地、测试、CI 可以尽量共用同一套启动思路。</li></ul><h3 id="可能的成本" tabindex="-1">可能的成本 <a class="header-anchor" href="#可能的成本" aria-label="Permalink to &quot;可能的成本&quot;">​</a></h3><ul><li>文件挂载、热更新、容器网络在部分机器上可能影响体验。</li><li>调试链路可能比直接跑本机进程更复杂。</li><li>如果拆得过细，容器数量过多，日常维护成本会上升。</li></ul><p>因此，更推荐的目标是：</p><ul><li>宿主机保留 <code>IDE + 浏览器 + Docker + Git</code></li><li>项目运行依赖尽量容器化</li><li>通过 <code>docker compose</code> 统一启动本地环境</li><li>通过脚本或 <code>devcontainer</code> 降低进入成本</li></ul><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><p>以下场景尤其适合采用 Docker 开发模式：</p><ul><li>团队成员较多，环境经常不一致</li><li>项目依赖较多，本地安装复杂</li><li>涉及多服务联调，例如前端 + API + 数据库 + Redis + 消息队列</li><li>需要让开发、测试、CI 尽可能使用相似环境</li></ul><h3 id="一句话建议" tabindex="-1">一句话建议 <a class="header-anchor" href="#一句话建议" aria-label="Permalink to &quot;一句话建议&quot;">​</a></h3><p>如果团队问“能不能 all in Docker”，更合适的回答是：<strong>项目开发环境可以尽量 all in Docker，但团队工作方式应该坚持 docker-first，而不是 docker-only。</strong></p><h2 id="标准开发流程" tabindex="-1">标准开发流程 <a class="header-anchor" href="#标准开发流程" aria-label="Permalink to &quot;标准开发流程&quot;">​</a></h2><p>标准开发流程适合正式项目、跨团队协作项目，以及对质量、合规、可维护性要求较高的功能。</p><h3 id="_1-需求澄清" tabindex="-1">1. 需求澄清 <a class="header-anchor" href="#_1-需求澄清" aria-label="Permalink to &quot;1. 需求澄清&quot;">​</a></h3><ul><li>明确业务目标、使用场景、边界条件和优先级。</li><li>补齐 PRD、流程图、原型、验收标准等输入材料。</li><li>识别外部依赖：第三方服务、数据库变更、权限审批、上线窗口等。</li></ul><p><strong>阶段产出</strong></p><ul><li>需求文档或确认记录</li><li>验收标准</li><li>风险与依赖清单</li></ul><h3 id="_2-技术方案设计" tabindex="-1">2. 技术方案设计 <a class="header-anchor" href="#_2-技术方案设计" aria-label="Permalink to &quot;2. 技术方案设计&quot;">​</a></h3><ul><li>确认技术栈、模块边界、数据结构、接口契约和异常处理方案。</li><li>评估性能、安全、可观测性和回滚策略。</li><li>对复杂功能进行任务拆分和工作量评估。</li></ul><p><strong>阶段产出</strong></p><ul><li>技术方案文档</li><li>接口定义</li><li>排期与负责人</li></ul><h3 id="_3-设计与开发准备" tabindex="-1">3. 设计与开发准备 <a class="header-anchor" href="#_3-设计与开发准备" aria-label="Permalink to &quot;3. 设计与开发准备&quot;">​</a></h3><ul><li>UI/UX 出具设计稿，与产品、开发共同确认交互细节。</li><li>建立开发分支、联调环境、测试数据与配置项。</li><li>明确埋点、权限、监控、日志等非功能需求。</li></ul><h3 id="_4-编码实现" tabindex="-1">4. 编码实现 <a class="header-anchor" href="#_4-编码实现" aria-label="Permalink to &quot;4. 编码实现&quot;">​</a></h3><ul><li>按模块拆分任务，避免多人同时改同一片核心逻辑。</li><li>优先完成数据结构、接口契约与核心链路，再补充边界功能。</li><li>关键逻辑必须补充单元测试或至少具备可复现的验证方式。</li></ul><h3 id="_5-联调与测试" tabindex="-1">5. 联调与测试 <a class="header-anchor" href="#_5-联调与测试" aria-label="Permalink to &quot;5. 联调与测试&quot;">​</a></h3><ul><li>前后端联调：接口字段、错误码、空态、权限校验全部核对。</li><li>测试覆盖：功能测试、回归测试、关键链路验证、必要的性能测试。</li><li>对高风险模块增加灰度或演练步骤。</li></ul><h3 id="_6-审查与上线" tabindex="-1">6. 审查与上线 <a class="header-anchor" href="#_6-审查与上线" aria-label="Permalink to &quot;6. 审查与上线&quot;">​</a></h3><ul><li>通过 Pull Request 进行代码审查，重点关注业务正确性、可维护性与风险点。</li><li>上线前完成变更说明、回滚方案和上线检查清单。</li><li>发布后观察日志、监控、告警与核心业务指标。</li></ul><h3 id="_7-复盘与沉淀" tabindex="-1">7. 复盘与沉淀 <a class="header-anchor" href="#_7-复盘与沉淀" aria-label="Permalink to &quot;7. 复盘与沉淀&quot;">​</a></h3><ul><li>记录需求偏差、实现问题、测试遗漏、发布风险。</li><li>将可复用方案沉淀为规范、模板或脚手架。</li></ul><h2 id="快速迭代模式" tabindex="-1">快速迭代模式 <a class="header-anchor" href="#快速迭代模式" aria-label="Permalink to &quot;快速迭代模式&quot;">​</a></h2><p>快速迭代模式不是“省流程”，而是“缩短反馈回路”。它适合原型验证、MVP、内部工具、活动页或新方向探索。</p><h3 id="推荐节奏" tabindex="-1">推荐节奏 <a class="header-anchor" href="#推荐节奏" aria-label="Permalink to &quot;推荐节奏&quot;">​</a></h3><ol><li><strong>聚焦目标</strong>：只定义本轮必须验证的 1 到 3 个核心问题。</li><li><strong>压缩范围</strong>：明确什么做、什么不做，优先交付最短路径。</li><li><strong>快速设计</strong>：用草图、简版流程图、接口约定替代厚文档。</li><li><strong>并行推进</strong>：前端、后端、设计同步推进，但接口和状态字段必须先对齐。</li><li><strong>每日同步</strong>：简短同步进度、风险、依赖和变更。</li><li><strong>即时验证</strong>：每天至少保证一次可运行、可演示或可测试的版本。</li><li><strong>尽早反馈</strong>：让业务方、测试方、真实用户尽快看到可用结果。</li><li><strong>按反馈继续迭代</strong>：保留有效方案，快速丢弃无效方向。</li></ol><h3 id="适用前提" tabindex="-1">适用前提 <a class="header-anchor" href="#适用前提" aria-label="Permalink to &quot;适用前提&quot;">​</a></h3><ul><li>业务允许试错，短期内更重视验证速度。</li><li>功能边界可控，不直接影响核心交易或核心资产安全。</li><li>团队可以保持高频沟通，且负责人能快速拍板。</li></ul><h3 id="常见风险" tabindex="-1">常见风险 <a class="header-anchor" href="#常见风险" aria-label="Permalink to &quot;常见风险&quot;">​</a></h3><ul><li>没有明确“本轮不做什么”，导致需求不断膨胀。</li><li>只顾速度，忽略接口约定，造成后续返工。</li><li>演示版本直接演变成线上版本，却没有补齐测试和治理。</li></ul><h2 id="两种模式如何切换" tabindex="-1">两种模式如何切换 <a class="header-anchor" href="#两种模式如何切换" aria-label="Permalink to &quot;两种模式如何切换&quot;">​</a></h2><p>项目往往不是从头到尾只采用一种模式，常见切换方式如下：</p><ul><li><strong>探索期使用快速迭代</strong>：先验证需求是否成立、用户是否买单。</li><li><strong>方案收敛后切回标准流程</strong>：补齐设计、测试、监控和发布治理。</li><li><strong>局部采用不同节奏</strong>：例如核心链路按标准流程执行，外围页面按快速迭代推进。</li></ul><p>当出现以下情况时，建议从快速迭代切回标准开发流程：</p><ul><li>需求已经稳定，进入长期维护阶段。</li><li>开始涉及权限、支付、风控、日志审计等高风险能力。</li><li>参与角色增多，单靠口头同步已经无法保障一致性。</li></ul><h2 id="最低质量基线" tabindex="-1">最低质量基线 <a class="header-anchor" href="#最低质量基线" aria-label="Permalink to &quot;最低质量基线&quot;">​</a></h2><p>无论是哪种模式，以下要求都不应省略：</p><ul><li>提交前至少完成一次自测，确认主流程可走通。</li><li>代码变更要能被他人理解，命名、结构、注释保持一致性。</li><li>核心接口、关键页面、异常场景必须有验证记录。</li><li>通过 PR 合并代码，不直接向受保护分支推送。</li><li>上线前明确回滚方式、负责人和观察指标。</li></ul><h2 id="建议的交付物" tabindex="-1">建议的交付物 <a class="header-anchor" href="#建议的交付物" aria-label="Permalink to &quot;建议的交付物&quot;">​</a></h2><p>为便于协作与追踪，建议至少保留下列材料：</p><ul><li>需求说明或会议结论</li><li>技术方案或简版设计记录</li><li>任务拆分和负责人</li><li>测试记录或验收结果</li><li>上线说明、风险提示与回滚方案</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>标准开发流程解决的是“如何稳定交付”，快速迭代模式解决的是“如何更快获得反馈”。真正成熟的团队，不是只会一种模式，而是能根据业务阶段主动切换节奏。</p>',69))])}const x=t(h,[["render",c]]);export{m as __pageData,x as default};
